[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
$root=Join-Path $ProjectPath 'Research\Verification\Gate10R_ProcessReuse_5pct\v4';$manifestPath=Join-Path $root 'Gate10R_Attempt4_OfficialExecution1_Partial_Manifest.v4.json';$receiptPath=Join-Path $root 'Gate10R_Attempt4_OfficialExecution1_Failure_Receipt.v4.json';$checkpointPath=Join-Path $root 'gate10r-attempt4-official-failure-1.checkpoint.v4.json'
if(@(Get-Process Unity -ErrorAction SilentlyContinue).Count -ne 0){throw 'Unity is running.'};if(Test-Path -LiteralPath (Join-Path $ProjectPath 'Temp\UnityLockfile')){throw 'Project lock is present.'}
function Get-LowerSha([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()}
function Write-AtomicJson([string]$Path,$Value){if(Test-Path -LiteralPath $Path){throw "Refusing overwrite: $Path"};$json=($Value|ConvertTo-Json -Depth 60).Replace("`r`n","`n").Replace("`r","`n");if(-not$json.EndsWith("`n",[StringComparison]::Ordinal)){$json+="`n"};$tmp=$Path+'.tmp-'+[guid]::NewGuid().ToString('N');$encoding=New-Object Text.UTF8Encoding($false,$true);[IO.File]::WriteAllText($tmp,$json,$encoding);[IO.File]::Move($tmp,$Path)}
foreach($required in @('Gate10R_Attempt4_Execution_Receipt.v4.json','Gate10R_Attempt4_Preflight.summary.v4.json','UnitTests.summary.json','Compile\attempt4.summary.json','TelemetryProbe\v1.summary.json')){if(-not(Test-Path -LiteralPath (Join-Path $root $required)-PathType Leaf)){throw "Required prior evidence missing: $required"}}
$unit=Get-Content (Join-Path $root 'UnitTests.summary.json')-Raw|ConvertFrom-Json;$compile=Get-Content (Join-Path $root 'Compile\attempt4.summary.json')-Raw|ConvertFrom-Json;$telemetry=Get-Content (Join-Path $root 'TelemetryProbe\v1.summary.json')-Raw|ConvertFrom-Json
if($unit.passed -ne $true -or $compile.passed -ne $true -or $telemetry.passed -ne $true){throw 'A completed predecessor gate is not passing.'}
$files=@(Get-ChildItem -LiteralPath $root -Recurse -File -Force|Sort-Object FullName);$artifacts=@($files|ForEach-Object{[ordered]@{relativePath=$_.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');bytes=[long]$_.Length;sha256=Get-LowerSha $_.FullName}})
$manifest=[ordered]@{schemaVersion=1;manifestId='gate10r-attempt4-official-execution1-partial-v4';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-BEFORE-BLOCK-UNITY-START';artifactCount=$artifacts.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);artifacts=$artifacts;completedGates=@('official-preflight','unit-59-of-59','unity-compile','telemetry-probe');failedGate='block-plan-generation';blockUnityProcessesStarted=0;formalCampaign=$false};Write-AtomicJson $manifestPath $manifest
$receipt=[ordered]@{schemaVersion=1;receiptId='gate10r-attempt4-official-execution1-failure-v4';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-ATOMICALLY-CLOSED-RESUME-AUTHORIZED';attempt=4;officialExecutionOrdinal=1;failedGate='block-verification-plan-generation';failureClass='PROVENANCE-COMPATIBILITY-FIELD-MISSING';message="New-Gate10RBlockPlan requires provenance.config/specification/testDesign/executionAuthorization/unityCommand compatibility fields; base v4 provenance stores the same bindings in boundFiles[].";unityStartedForFailedGate=$false;completedEvidencePreserved=$true;partialManifestSha256=Get-LowerSha $manifestPath;originalExecutionReceiptSha256=Get-LowerSha (Join-Path $root 'Gate10R_Attempt4_Execution_Receipt.v4.json');resumeAuthorized=$true;resumeStartGate='block-verification';overwriteAllowed=$false;gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $receiptPath $receipt
$checkpoint=[ordered]@{schemaVersion=1;checkpointKind='gate10r-attempt4-official-failure-1';savedAtUtc=[DateTime]::UtcNow.ToString('o');status='GATE10R-ATTEMPT4-OFFICIAL-EXECUTION1-FAILED-CLOSED-RESUME-BLOCK-GATE-AUTHORIZED';attempt=4;officialExecutionCount=1;resumeCount=0;failureReceiptSha256=Get-LowerSha $receiptPath;partialManifestSha256=Get-LowerSha $manifestPath;preservedPassingGates=@('unit','compile','telemetry');nextGate='block-verification';unityProcessCount=0;projectLockPresent=$false;gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $checkpointPath $checkpoint
$checkpoint|ConvertTo-Json -Depth 15
